findings.suggestion:
function durationText(seconds: number): string {
  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const parts = [
    [hours, "h", hours > 0],
    [minutes, "m", minutes > 0 || hours > 0],
    [seconds % 60, "s", true],
  ] as const
  return parts
    .filter(([, , show]) => show)
    .map(([count, unit]) => `${count}${unit}`)
    .join(" ")
}

